/**
 * facilities.ts — server-side data access for the facilities directory.
 * Data is generated by scripts/ingest-facilities.mjs from public sources
 * (SAMHSA National Directory + CA DHCS roster) into src/data/facilities/.
 */
import { facilityPolicies } from "@/lib/facilityIndexing.mjs";
import indexData from "@/data/facilities/index.json";

export interface FacilityLicense {
  applicationType: string;
  programCode: string;
  licenseExpiration: string | null;
  treatmentCapacity: number | null;
  rosterFacilityName: string;
  legalEntityName: string;
  rosterPhone: string | null;
  rosterStreet1: string;
  matchBasis: string;
}

export interface Facility {
  name: string;
  dba: string | null;
  street1: string;
  street2: string | null;
  city: string;
  citySlug: string;
  state: string;
  stateName: string;
  zip: string;
  phone: string | null;
  intakePhone: string | null;
  website: string | null;
  careTypes: string[];
  settings: string[];
  payment: string[];
  groupsServed: string[];
  languages: string[];
  agesServed: string[];
  ownership: string | null;
  nppesNpi: string | null;
  license: FacilityLicense | null;
  slug: string;
  path: string;
}

export interface CaLicenseRecord {
  applicationNumber: string;
  legalEntityName: string;
  facilityName: string;
  street1: string;
  city: string;
  zip: string;
  phone: string | null;
  applicationType: string;
  programCode: string;
  treatmentCapacity: number | null;
  licenseExpiration: string | null;
  targetPopulation: string | null;
  county: string;
  normFacilityName: string;
  normLegalName: string;
}

export interface DirectoryIndex {
  generatedAt: string;
  sources: Array<{
    id: string;
    label: string;
    note?: string;
    status?: string;
    retrievedAt: string | null;
    rows: number;
  }>;
  totals: {
    facilities: number;
    states: number;
    caFacilities: number;
    caLicenseMatched: number;
    caLicenseRecords: number;
  };
  states: Array<{
    code: string;
    name: string;
    facilityCount: number;
    cities: Array<{ name: string; slug: string; count: number }>;
  }>;
}

export function getDirectoryIndex(): DirectoryIndex {
  return indexData as DirectoryIndex;
}

const stateCache = new Map<string, Facility[]>();

export async function getStateFacilities(stateCode: string): Promise<Facility[] | null> {
  const code = stateCode.toUpperCase();
  if (!getDirectoryIndex().states.some((s) => s.code === code)) return null;
  const cached = stateCache.get(code);
  if (cached) return cached;
  try {
    const mod = (await import(`@/data/facilities/by-state/${code}.json`)) as { default: Facility[] };
    stateCache.set(code, mod.default);
    return mod.default;
  } catch {
    return null;
  }
}

export async function getFacility(
  stateCode: string,
  citySlug: string,
  slug: string,
): Promise<Facility | null> {
  const list = await getStateFacilities(stateCode);
  if (!list) return null;
  return list.find((f) => f.citySlug === citySlug && f.slug === slug) ?? null;
}

export async function getCaLicenses(): Promise<CaLicenseRecord[]> {
  const mod = (await import("@/data/facilities/ca-licenses.json")) as { default: CaLicenseRecord[] };
  return mod.default;
}

/** Load only server-side; reused by the sitemap and national context. */
export async function getAllFacilities(): Promise<Facility[]> {
  const lists = await Promise.all(getDirectoryIndex().states.map(s => getStateFacilities(s.code)));
  if (lists.some(list => list === null)) throw new Error("Directory dataset unavailable");
  return lists.flatMap(list => list!);
}

const policyCache = new Map<string, ReturnType<typeof facilityPolicies>>();
export async function getFacilityIndexPolicy(facility: Facility) {
  let policies = policyCache.get(facility.state);
  if (!policies) {
    const facilities = await getStateFacilities(facility.state);
    if (!facilities) throw new Error("Directory dataset unavailable");
    policies = facilityPolicies(facilities);
    policyCache.set(facility.state, policies);
  }
  return policies.get(facility.path)!;
}
